import { describe, it, expect, beforeEach, afterEach } from "vitest";
import { mkdtempSync, mkdirSync, rmSync, writeFileSync, readFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const cli = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "cli.mjs");

describe("todos lint checks the recorded graph", () => {
  let dir;
  let boardFile;
  const savedAppData = process.env.APPDATA;

  // Fixture tasks are project-LESS on purpose: the board scope is "this project
  // plus project-less tasks", so a global task is in scope whatever directory
  // vitest happens to run from.
  const task = (n, extra = {}) => ({
    id: `t${n}`,
    number: n,
    subject: `узел ${n}`,
    status: "queue",
    ...extra,
  });

  const board = (...todos) =>
    writeFileSync(boardFile, JSON.stringify({ version: 2, todos }, null, 2));

  const lint = (...args) => {
    try {
      return {
        code: 0,
        out: execFileSync(process.execPath, [cli, "todos", "lint", ...args], {
          encoding: "utf8",
          env: { ...process.env, APPDATA: dir },
          windowsHide: true,
        }),
      };
    } catch (e) {
      return { code: e.status, out: (e.stdout || "") + (e.stderr || "") };
    }
  };

  beforeEach(() => {
    dir = mkdtempSync(path.join(os.tmpdir(), "cut-lint-"));
    // The app data directory is the tracker's to create, exactly as in real use.
    mkdirSync(path.join(dir, "com.claude-usage-tracker.app"), { recursive: true });
    boardFile = path.join(dir, "com.claude-usage-tracker.app", "todos.json");
  });

  afterEach(() => {
    if (savedAppData === undefined) delete process.env.APPDATA;
    else process.env.APPDATA = savedAppData;
    rmSync(dir, { recursive: true, force: true });
  });

  it("says nothing about a graph that keeps every invariant, and exits 0", () => {
    board(
      task(1, { verify: "npm test", kind: "auto" }),
      task(2, { depends_on: ["t1"] }),
    );
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/2 node\(s\) checked/);
    expect(out).toMatch(/nothing violates the process language/);
  });

  it("reads the board and never writes it", () => {
    board(task(1, { kind: "auto" }), task(2, { on_issue: "gone" }));
    const before = readFileSync(boardFile, "utf8");
    lint();
    lint("--json");
    expect(readFileSync(boardFile, "utf8")).toBe(before);
  });

  // §11/§15: a limit withdrawn AFTER the transition was declared is how a board
  // reaches this state — `set on-issue` itself refuses without one.
  it("errors on an ?issue transition left without a retry limit", () => {
    board(task(1), task(2, { on_issue: "t1" }));
    const { code, out } = lint();
    expect(code).toBe(1);
    expect(out).toMatch(/#2: on-issue without a retry limit/);
    expect(out).toMatch(/1 error\(s\), 0 warning\(s\)/);
  });

  it("errors on an ?issue arrow left hanging by a deleted task", () => {
    board(task(1, { on_issue: "t9", retry_limit: 2 }));
    const { out, code } = lint();
    expect(code).toBe(1);
    expect(out).toMatch(/#1: on-issue points at "t9", which is not a task on this board any more/);
  });

  it("errors on a dependency pointing at a task that no longer exists", () => {
    board(task(1, { depends_on: ["t9"] }));
    const { out, code } = lint();
    expect(code).toBe(1);
    expect(out).toMatch(/#1 needs "t9", which is not a task on this board any more/);
  });

  it("errors on a cycle written into depends_on and names the ring", () => {
    board(task(1, { depends_on: ["t2"] }), task(2, { depends_on: ["t1"] }));
    const { out, code } = lint();
    expect(code).toBe(1);
    expect(out).toMatch(/needs form a cycle: #1 -> #2 -> #1/);
  });

  it("warns when independent open nodes promise the same path, regardless of slash style", () => {
    board(task(1, { produces: ["src\\TodoWindow.vue"] }), task(2, { produces: ["src/TodoWindow.vue"] }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1 and #2 both produce "src\/TodoWindow\.vue" without a needs path between them/);
    expect(out).toMatch(/add a needs edge or make one step/);
  });

  it("does not warn about shared produces when needs connect the nodes transitively", () => {
    board(
      task(1, { produces: ["src/TodoWindow.vue"] }),
      task(2, { depends_on: ["t1"] }),
      task(3, { depends_on: ["t2"], produces: ["src/TodoWindow.vue"] }),
    );
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("does not compare a closed node's produces with open work", () => {
    board(task(1, { status: "done", produces: ["src/TodoWindow.vue"], outcome: "ok" }), task(2, { produces: ["src/TodoWindow.vue"] }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  // A gate is a legal graph — the node just cannot close itself, so this is a
  // note about what the runner will do, not a fault.
  it("only warns on auto without a verify, and calls it a gate", () => {
    board(task(1, { kind: "auto" }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1: auto with no verify runs as a GATE/);
  });

  it("warns when a scripts/cli step's verify omits the layers test", () => {
    board(task(1, { produces: ["scripts\\cli\\process\\apply.mjs"], verify: "npm test" }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1: produces under scripts\/cli\/ but verify does not include .*layers\.test\.mjs/);

    board(task(1, {
      produces: ["scripts/cli/process/apply.mjs"],
      verify: "npm test && npx vitest run scripts/cli/kernel/layers.test.mjs",
    }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("warns when a broad promise includes an existing file over 1500 lines", () => {
    const large = path.join(dir, "large.mjs");
    writeFileSync(large, Array.from({ length: 1501 }, () => "x").join("\n"));
    board(task(1, { produces: [large, "src/a.mjs", "src/b.mjs", "src/c.mjs"] }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1: шаг крупный — разрезать по produces/);
  });

  it("errors on red declared without red-tests, and on red-tests without red", () => {
    board(task(1, { kind: "auto", red: "npm run test:red" }));
    expect(lint().out).toMatch(/#1: red declared without red-tests/);
    board(task(1, { kind: "auto", red_tests: ["test/a.spec.js"] }));
    expect(lint().out).toMatch(/#1: red-tests declared without red/);
  });

  it("only warns when a red-tests path is not also in produces", () => {
    board(task(1, { kind: "auto", red: "npm run test:red", red_tests: ["test/a.spec.js"], produces: ["src/a.js"] }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1: red-tests path "test\/a\.spec\.js" is not declared in produces/);
    board(
      task(1, {
        kind: "auto",
        verify: "npm test",
        red: "npm run test:red",
        red_tests: ["test/a.spec.js"],
        produces: ["src/a.js", "test/a.spec.js"],
      }),
    );
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("only warns when red is declared on a manual node — a gate never runs it", () => {
    board(task(1, { red: "npm run test:red", red_tests: ["test/a.spec.js"] }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/#1: red declared on a manual node — a gate never runs it/);
  });

  it("requires flow for auto code in the configured languages, with an explained n/a escape hatch", () => {
    board(task(1, { kind: "auto", produces: ["src/Notifier.cs"] }));
    let result = lint();
    expect(result.code).toBe(1);
    expect(result.out).toMatch(/#1: auto step produces configured flow-language code but has no flow/);

    board(task(1, { kind: "auto", produces: ["src/Notifier.cs"], flow: "n/a" }));
    result = lint();
    expect(result.code).toBe(1);
    expect(result.out).toMatch(/#1: flow: n\/a needs a reason/);

    board(task(1, { kind: "auto", verify: "npm test", produces: ["src/Notifier.cs"], flow: "n/a generated code has no method body" }));
    result = lint();
    expect(result.code).toBe(0);
    expect(result.out).toMatch(/nothing violates/);

    board(task(1, { kind: "auto", produces: ["src/Notifier.cs"], flow: "placeholder" }));
    result = lint();
    expect(result.code).toBe(1);
    expect(result.out).toMatch(/#1: flow must be a method delta, a list of them, or flow: n\/a <reason>/);
    const delta = (method) => ({ file: "src/Notifier.cs", method, change: [], preserve: "all" });
    board(task(1, { kind: "auto", verify: "npm test", produces: ["src/Notifier.cs"], flow: [delta("SendSms"), delta("SendEmail")] }));
    result = lint();
    expect(result.code).toBe(0);
    expect(result.out).toMatch(/nothing violates/);

    board(task(1, { kind: "auto", verify: "npm test", produces: ["src/Notifier.cs"], flow: [] }));
    expect(lint().code).toBe(1);
  });

  it("uses flowLanguages for this project, including Rust and TS/JS extension families", () => {
    const project = path.basename(process.cwd());
    writeFileSync(path.join(dir, "com.claude-usage-tracker.app", "settings.json"), JSON.stringify({
      flowLanguages: { [project]: ["rs", "ts", "js"] },
    }));
    board(task(1, { kind: "auto", produces: ["src/notify.rs", "src/ui.tsx", "scripts/check.mjs"] }));
    expect(lint().out).toMatch(/configured flow-language code but has no flow/);
    board(task(1, { kind: "auto", produces: ["src/notify.rs"], flow: "n/a generated binding" }));
    expect(lint().code).toBe(0);
    board(task(1, { kind: "auto", produces: ["src/ignored.py"] }));
    expect(lint().code).toBe(0);
  });

  it("accepts high and sensitive risk, and errors on any other value", () => {
    board(task(1, { risk: "medium" }));
    expect(lint().out).toMatch(/#1: invalid risk "medium".*accepted values: "high" \| "sensitive"/);
    board(task(1, { risk: "high" }));
    expect(lint().out).toMatch(/nothing violates/);
    board(task(1, { risk: "sensitive" }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("validates a recorded size but does not require one on existing graphs", () => {
    board(task(1, { kind: "auto", verify: "npm test" }));
    expect(lint().out).toMatch(/nothing violates/);
    board(task(1, { size: "XL" }));
    expect(lint().out).toMatch(/invalid size "XL".*S \| M \| L/);
    board(task(1, { size: "L" }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("warns that a change with no budget cannot be run unattended, and stays quiet once it has one", () => {
    board(task(1, { change: true, depends_on: ["t2"] }), task(2));
    expect(lint().out).toMatch(/change #1 "узел 1": no budget declared on the group/);
    board(task(1, { change: true, depends_on: ["t2"], budget_usd: 5 }), task(2));
    expect(lint().out).toMatch(/nothing violates/);
  });

  // A ceiling bounds a run that is still ahead. Over a group whose members are
  // all closed there is no run to bound, and the number would be invented — the
  // one thing §15 forbids ("никаких значений из воздуха").
  it("says nothing about the budget of a change with nothing left to run", () => {
    board(task(1, { change: true, depends_on: ["t2"] }), task(2, { status: "done" }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  it("warns about a node closed on a promise nobody reconciled", () => {
    board(task(1, { status: "done", produces: ["src/a.ts"] }));
    expect(lint().out).toMatch(/#1: closed with 1 promised output\(s\) and no reconciled outcome/);
    board(task(1, { status: "done", produces: ["src/a.ts"], outcome: "ok" }));
    expect(lint().out).toMatch(/nothing violates/);
  });

  // Every other rule is about the NEXT run, and a closed node has none: warning
  // about a gate that will never open or a transition that will never fire is
  // exactly the noise that makes a linter get ignored.
  it("holds the run-time rules off closed nodes", () => {
    board(task(1, { status: "done", kind: "auto", on_issue: "gone" }));
    const { code, out } = lint();
    expect(code).toBe(0);
    expect(out).toMatch(/nothing violates/);
  });

  it("with a change argument checks that subtree only", () => {
    board(
      task(1, { change: true, budget_usd: 5, depends_on: ["t2"] }),
      task(2, { kind: "auto" }),
      task(3, { kind: "auto" }),
    );
    const inside = lint("1").out;
    expect(inside).toMatch(/2 node\(s\) checked/);
    expect(inside).toMatch(/#2: auto with no verify/);
    expect(inside).not.toMatch(/#3/);
    expect(lint().out).toMatch(/#3: auto with no verify/);
    expect(lint("99").code).toBe(1);
  });

  it("hands the same findings out machine-readably", () => {
    board(task(1, { on_issue: "t2" }), task(2, { kind: "auto" }));
    const r = JSON.parse(lint("--json").out);
    expect(r.ok).toBe(false);
    expect(r.checked).toBe(2);
    expect(r.findings.map((f) => [f.rule, f.severity, f.task])).toEqual([
      ["on-issue-without-retry", "error", "#1"],
      ["auto-without-verify", "warning", "#2"],
    ]);
  });

  it("infers retry on apply but keeps the legacy-board lint rule", () => {
    writeFileSync(
      path.join(dir, "graph.yaml"),
      ["change: CHANGE: retry inference", "steps:", "  1:", "    title: A", "  2:", "    title: B", "    on-issue: 1"].join("\n"),
    );
    const fromApply = execFileSync(process.execPath, [cli, "todos", "apply", path.join(dir, "graph.yaml")], {
      encoding: "utf8",
      env: { ...process.env, APPDATA: dir },
      windowsHide: true,
    });
    board(task(1), task(2, { on_issue: "t1" }));
    const shared =
      "on-issue without a retry limit. A missing limit FORBIDS the transition, " +
      "it does not permit an endless one — declare retry on this node";
    expect(fromApply).toContain("выведено 2  retry=2");
    expect(fromApply).not.toContain(shared);
    expect(lint().out).toContain(shared);
  });
});

scripts/cli/process/plan-guard.test.mjs.source:
// Unit tests for the plan-format guard (`cli.mjs plan-guard`, t#318 + t#325).
//
// Four things are worth pinning, and they are not the same thing:
//   • the DEMAND — since t#325 the language is required of EVERY plan, prose
//     included. What used to be the guard's caution (judge only a text that
//     already looked like the language) is now a choice of message.
//   • the EXIT — `discussion: <reason>` is the one way past the demand, and the
//     reason is what keeps it from being the way past every plan. Both halves
//     are load-bearing: no exit means a session trapped in plan mode, a free
//     exit means the format is optional again.
//   • the WORDING — the refusal repeats the validator verbatim, because the whole
//     point of reusing apply.mjs is that a rule is stated once.
//   • the CONTRACT — the PreToolUse deny payload, and the promise that no input
//     whatsoever makes the hook exit non-zero or print anything but that payload.

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { execFileSync } from "node:child_process";
import { existsSync, readFileSync, mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import {
  planCandidates,
  inspectPlan,
  buildRefusal,
  buildFormatRefusal,
  buildBlankDiscussionRefusal,
  buildContradictionRefusal,
  discussionDeclaration,
  isReason,
  decide,
  architectDecision,
  architectGateState,
  planReviewStore,
  parallelismBlock,
  planFormatDoc,
  planFormatIssuesDoc,
  planFormatCuttingDoc,
} from "./plan-guard.mjs";
import { readDocument, validate } from "./apply.mjs";
import { emptyAgentConfig } from "../agents/agents.mjs";
import { WAVE_RULES } from "./wave.mjs";

const CLI = path.join(path.dirname(fileURLToPath(import.meta.url)), "..", "..", "cli.mjs");

const VALID = `change: "CHANGE: приём вебхуков"
vision: |
  Должен появиться приём вебхуков, который не теряет события.
parallel: 2
budget: 25
steps:
  1:
    title: Завожу таблицу событий
    why: |
      Приём обязан отвечать быстро и не зависеть от обработчика.
    produces: [migrations/007_events.sql]
    verify: npm run test:webhook
    kind: auto
    size: S
  2:
    title: Пишу обработчик очереди
    why: |
      Повторная доставка — норма, поэтому обработчик идемпотентен.
    needs: [1]
    verify: npm run test:queue
    retry: 3
    on-issue: 1
    kind: auto
    size: M
`;

const BROKEN = `change: "CHANGE: приём вебхуков"
vision: |
  Должен появиться приём вебхуков.
budget: 25
steps:
  1:
    title: Завожу таблицу событий
    kind: manual
  2:
    title: Пишу обработчик очереди
    needs: [1]
    on-issue: 2
    kind: manual
`;

const fenced = (yaml, lang = "yaml") => "Вот план:\n\n```" + lang + "\n" + yaml + "```\n";

const exitPlan = (plan) => ({ tool_name: "ExitPlanMode", tool_input: { plan } });

describe("the plan-format document", () => {
  it("keeps every former issue/cutting heading in its routed document", () => {
    for (const file of [planFormatDoc(), planFormatIssuesDoc(), planFormatCuttingDoc()])
      expect(existsSync(file)).toBe(true);
    expect(readFileSync(planFormatIssuesDoc(), "utf8")).toMatch(/^## 5\. When a runner task does not converge$/m);
    expect(readFileSync(planFormatCuttingDoc(), "utf8")).toMatch(/^## 6\. Cutting the draft plan$/m);
  });
});

// A discussion as it is actually written: the declaration, then prose that has no
// intention of parsing.
const DISCUSSION = [
  "discussion: разбираю, почему повтор вебхука доходит дважды — работу этим",
  "  планом не завожу, решаем после",
  "",
  "## Что я вижу",
  "Провайдер шлёт повтор через 30 секунд, а транзакция ещё открыта.",
].join("\n");

describe("planCandidates · what reads as a document of the language", () => {
  it("takes a bare document and one inside a fence", () => {
    expect(planCandidates(VALID)).toHaveLength(1);
    expect(planCandidates(fenced(VALID)).length).toBeGreaterThan(0);
  });

  it("takes a document introduced by a paragraph of prose", () => {
    // The parser stops at the first line that is not `key: value`, so the
    // candidate has to be trimmed to start at the document's first key.
    const withPreamble = "Посмотрел код, вот что предлагаю.\n\n" + VALID;
    const [doc] = planCandidates(withPreamble);
    expect(doc.startsWith("change:")).toBe(true);
    expect(readDocument(doc).steps).toHaveLength(2);
  });

  // t#325 lowered the bar from two document keys to one. The reason is the
  // message, not the verdict: a text with a key can be answered in the
  // validator's own sentences, a text without one only in general terms — and
  // both are refused either way now.
  it("takes a one-step plan whose only document key is `steps`", () => {
    const oneStep = "steps:\n  1:\n    task: 318\n    why: |\n      Чиню в приёме.\n";
    expect(planCandidates(oneStep)).toHaveLength(1);
    expect(inspectPlan(oneStep, { onBoard: () => true }).errors).toEqual([]);
    expect(decide(exitPlan(oneStep), { onBoard: () => true })).toBeNull();
  });

  it("reads only column 0 — an indented key belongs to a step, not the document", () => {
    expect(planCandidates("  change: X\n  steps:\n    1:\n      title: Шаг\n")).toEqual([]);
  });

  it("finds nothing in a text that never names a key of the language", () => {
    const prose = ["## План", "", "Разберусь, почему парсер роняет `t#299`, и починю."].join("\n");
    expect(planCandidates(prose)).toEqual([]);
    expect(inspectPlan(prose).attempted).toBe(false);
  });
});

// The half of t#325 that is a real change of behaviour: what used to pass now
// does not. Each of these was an explicit "let it through" before.
describe("decide · the language is required of every plan", () => {
  const refusalFor = (text) => {
    const seen = decide(exitPlan(text));
    expect(seen).not.toBeNull();
    expect(seen.permissionDecision).toBe("deny");
    return seen.permissionDecisionReason;
  };

  it("refuses a prose plan, and names both ways forward", () => {
    const prose = [
      "## План",
      "",
      "Разберусь, почему парсер роняет `t#299`, и починю на месте.",
      "",
      "1. Читаю apply.mjs",
      "2. Чиню dequote",
    ].join("\n");
    const reason = refusalFor(prose);
    expect(reason).toContain("REFUSED");
    // Rewrite it as the file…
    expect(reason).toContain(planFormatDoc());
    // …or say it is not work. A refusal that names only the first is the trap
    // this exit exists to avoid.
    expect(reason).toContain("discussion:");
  });

  it("refuses a quoted CI fragment in the validator's own words", () => {
    // A GitHub Actions job: `steps:` at column 0 and list items with no title.
    // It now reads as a broken document rather than as none, which is the more
    // useful answer — the session is told which rule it broke.
    const ci = fenced("steps:\n  - uses: actions/checkout@v4\n  - run: npm ci\n");
    const reason = refusalFor(ci);
    expect(reason).toContain("title");
  });

  it("refuses a plan that is only a heading", () => {
    expect(refusalFor("# План\n\nПочиню на месте.\n")).toContain("REFUSED");
  });
});

describe("discussion · the one declared way past the demand", () => {
  it("reads the reason off the declaration, including its continuation lines", () => {
    const { reason } = discussionDeclaration(DISCUSSION);
    expect(reason).toContain("повтор вебхука");
    expect(reason).toContain("решаем после");
  });

  it("takes a block scalar as well as an inline value", () => {
    const block = "discussion: |\n  Согласую подход к разбору вебхуков, задач не завожу.\n";
    expect(isReason(discussionDeclaration(block).reason)).toBe(true);
  });

  it("lets a declared discussion through untouched, prose and all", () => {
    expect(decide(exitPlan(DISCUSSION))).toBeNull();
  });

  it("is not a document of the language — it records nothing and parses nothing", () => {
    expect(planCandidates(DISCUSSION)).toEqual([]);
  });

  // The exit has to cost more than a word, or it is the exit from every plan.
  it("refuses the declaration without a reason", () => {
    for (const flag of ["discussion: true\n\n## План\nЧиню.", "discussion:\n\n## План\nЧиню."]) {
      const seen = decide(exitPlan(flag));
      expect(seen.permissionDecision).toBe("deny");
      expect(seen.permissionDecisionReason).toContain("without saying what is being");
    }
  });

  it("refuses a label too short to name anything", () => {
    expect(isReason("это разбор")).toBe(false);
    expect(isReason("разбираю причину дублей")).toBe(true);
    expect(decide(exitPlan("discussion: разбор\n\n## План\nЧиню.")).permissionDecision).toBe("deny");
  });

  // The declaration wins over anything else in the text, so a plan that declares
  // it AND writes steps would lose the steps in silence — approved, recorded
  // nowhere. Refused instead of resolved: the guard has no way to know which
  // half the session meant.
  it("refuses a plan that declares a discussion and still carries steps", () => {
    const both = DISCUSSION + "\n\n" + fenced(VALID);
    const seen = decide(exitPlan(both));
    expect(seen.permissionDecision).toBe("deny");
    expect(seen.permissionDecisionReason).toMatch(/2 task/);
    expect(seen.permissionDecisionReason).toMatch(/dropped in silence/);
  });

  it("reads no `discussion` that is not at column 0", () => {
    // Inside a step it is an unknown key, which `apply` warns about — not a
    // declaration about the whole plan.
    const inStep = "steps:\n  1:\n    title: Шаг\n    discussion: обсуждаем подход к делу\n";
    expect(discussionDeclaration(inStep)).toBeNull();
  });
});

describe("inspectPlan · the verdict", () => {
  it("passes a valid graph file, fenced or bare", () => {
    for (const text of [VALID, fenced(VALID), fenced(VALID, "")]) {
      const seen = inspectPlan(text);
      expect(seen.attempted).toBe(true);
      expect(seen.errors).toEqual([]);
    }
  });

  it("refuses a document that breaks a rule", () => {
    const seen = inspectPlan(BROKEN);
    expect(seen.attempted).toBe(true);
    expect(seen.errors).toHaveLength(1);
  });

  // The format document tells the session to read §1, whose sketch is full of
  // `<placeholders>` that do not validate. A model that pastes it above its real
  // plan must not be locked out of plan mode over the quotation.
  it("passes when ANY reading of the text is a valid graph", () => {
    const sketch =
      "Формат:\n\n```yaml\nchange: \"CHANGE: <name>\"\nvision: |\n  <...>\nparallel: <N>\nbudget: <usd>\nsteps:\n  <n>:\n    title: <the step phrase>\n    needs: [<n>, <n>]\n```\n\nМой план:\n\n" +
      fenced(VALID);
    expect(planCandidates(sketch).length).toBeGreaterThan(1);
    expect(inspectPlan(sketch).errors).toEqual([]);
    expect(decide(exitPlan(sketch))).toBeNull();
  });

  // A reference the file does not declare is legal when the board carries it, and
  // the caller is the one who knows. Unable to read the board → answer yes, never
  // refuse on a check that was not run.
  it("asks the caller whether an outside reference resolves", () => {
    const hanging = BROKEN.replace("needs: [1]", "needs: [t#299]").replace("on-issue: 2", "");
    expect(inspectPlan(hanging, { onBoard: () => true }).errors).toEqual([]);
    expect(inspectPlan(hanging, { onBoard: () => false }).errors).toHaveLength(1);
    expect(inspectPlan(hanging).errors).toEqual([]); // default: forgiving
  });

  it("never throws on garbage", () => {
    for (const text of ["", "   ", "�", "```yaml\n", "change:\nvision:\nsteps:\n"])
      expect(() => inspectPlan(text)).not.toThrow();
  });
});

describe("buildRefusal · one wording, owned by the validator", () => {
  const errors = validate(readDocument(BROKEN)).errors;

  it("repeats the validator's sentence VERBATIM", () => {
    // The claim the guard makes is that its refusal and `todos apply`'s refusal
    // are the same text. Compared against the validator's own output, not a copy.
    expect(errors).toHaveLength(1);
    expect(errors[0].length).toBeGreaterThan(40);
    expect(decide(exitPlan(BROKEN)).permissionDecisionReason).toContain(errors[0]);
  });

  it("says the plan never reached the user, and where the format is", () => {
    const reason = buildRefusal(errors);
    expect(reason).toContain("REFUSED");
    expect(reason).toContain("never reached the user");
    expect(reason).toContain(planFormatDoc());
    expect(reason).toContain("§1");
    expect(reason).not.toContain(planFormatIssuesDoc());
    expect(reason).not.toContain(planFormatCuttingDoc());
  });

  it("labels warnings as not being the reason, and omits the block when there are none", () => {
    expect(buildRefusal(["e"], ["w"])).toContain("not the reason");
    expect(buildRefusal(["e"], [])).not.toContain("not the reason");
  });

  it("puts out and measure conventions in refusals that need them", () => {
    const reason = buildRefusal(["out[1]: why is required", "measure[1]: how is required"]);
    expect(reason).toContain("Field contract:");
    expect(reason).toMatch(/`out` items are durable exclusions/);
    expect(reason).toMatch(/`measure` items describe a user-visible observation/);
    expect(buildRefusal(["needs form a cycle"])).not.toContain("Field contract:");
  });

  // The two refusals t#325 added carry no rule of their own — they carry the
  // ways out. A refusal that names only the format is a session trapped in plan
  // mode; one that names only the exit teaches that prose plus a flag is a plan.
  it("offers the format AND the discussion exit when the plan is not the language", () => {
    const reason = buildFormatRefusal();
    expect(reason).toContain(planFormatDoc());
    expect(reason).toContain("§1 and §2");
    expect(reason).toContain("discussion:");
    expect(reason).toMatch(/does NOT start work/i);
    expect(reason).toMatch(/discussion: true` is refused/);
  });

  it("names both halves of the contradiction and what each one does", () => {
    const reason = buildContradictionRefusal(3);
    expect(reason).toContain("3 task(s)");
    expect(reason).toMatch(/records NOTHING/);
    expect(reason).toMatch(/opens the tasks/);
    expect(reason).toContain("§3");
    expect(reason).toContain(planFormatDoc());
  });

  it("asks for the reason, not for the format, when the declaration is bare", () => {
    const reason = buildBlankDiscussionRefusal();
    expect(reason).toMatch(/what is being/i);
    // …and still says where to go if the plan does start work after all.
    expect(reason).toContain(planFormatDoc());
    expect(reason).toContain("§3");
  });

  // A warning is not a refusal: `auto` with no verify and a change with no budget
  // are accepted by `todos apply`, so the guard must accept them too.
  it("does not refuse a plan whose only findings are warnings", () => {
    const warned = "change: \"CHANGE: X\"\nvision: |\n  Что-то.\nsteps:\n  1:\n    title: Делаю\n    kind: auto\n    size: S\n";
    const seen = inspectPlan(warned);
    expect(seen.errors).toEqual([]);
    expect(seen.warnings.length).toBeGreaterThan(0);
    expect(decide(exitPlan(warned))).toBeNull();
  });
});

describe("decide · the PreToolUse contract", () => {
  it("returns the deny payload Claude Code reads", () => {
    expect(decide(exitPlan(BROKEN))).toMatchObject({
      hookEventName: "PreToolUse",
      permissionDecision: "deny",
    });
  });

  it("holds no opinion on a valid plan, an empty plan or a missing payload", () => {
    expect(decide(exitPlan(VALID))).toBeNull();
    expect(decide(exitPlan(""))).toBeNull();
    expect(decide(exitPlan("   \n "))).toBeNull();
    expect(decide({ tool_name: "ExitPlanMode" })).toBeNull();
    expect(decide({})).toBeNull();
    expect(decide(null)).toBeNull();
  });

  it("judges nothing but ExitPlanMode, however broadly it gets wired", () => {
    expect(decide({ tool_name: "Bash", tool_input: { plan: BROKEN } })).toBeNull();
    expect(decide({ tool_name: "Write", tool_input: { plan: BROKEN } })).toBeNull();
  });
});

describe("architectDecision · configured lifecycle hook", () => {
  const AVAILABLE = {
    mode: "agent",
    available: true,
    candidate: { label: "anthropic/claude-opus-5-5" },
    candidates: [],
  };

  it("lets an approved plan continue and passes the workspace to the architect", () => {
    const calls = [];
    const seen = architectDecision(
      { ...exitPlan(VALID), cwd: "D:\\repo" },
      (duty, prompt, opts) => {
        calls.push({ duty, prompt, opts });
        return { ok: true, text: "No structural findings.\nVERDICT: approve" };
      },
      { gate: AVAILABLE },
    );
    expect(seen).toBeNull();
    expect(calls).toHaveLength(1);
    expect(calls[0]).toMatchObject({ duty: "architect", opts: { cwd: "D:\\repo" } });
    expect(calls[0].prompt).toContain(VALID);
  });

  it("blocks a plan when the architect reports an obligation issue", () => {
    const seen = architectDecision(exitPlan(VALID), () => ({
      ok: true,
      text: "Step 2 has no dependency on step 1.\nVERDICT: issue",
    }), { gate: AVAILABLE });
    expect(seen).toMatchObject({ hookEventName: "PreToolUse", permissionDecision: "deny" });
    expect(seen.permissionDecisionReason).toContain("Step 2 has no dependency");
  });

  it("reports a model-call error but leaves normal user approval in place", () => {
    const decision = architectDecision(
      exitPlan(VALID),
      () => ({ ok: false, error: "provider timed out" }),
      { gate: AVAILABLE },
    );
    expect(decision).not.toHaveProperty("permissionDecision");
    expect(decision.additionalContext).toContain("ARCHITECT CHECK FAILED OPEN");
    expect(decision.additionalContext).toContain("anthropic/claude-opus-5-5");
    expect(decision.additionalContext).toContain("provider timed out");
  });

  it("blocks agent mode with no candidate and names the explicit off command", () => {
    const decision = architectDecision(exitPlan(VALID), () => { throw new Error("must not run"); }, {
      gate: {
        mode: "agent",
        available: false,
        candidate: null,
        candidates: [{ label: "openai/gpt-5.6-terra", binary: { reason: "missing" } }],
      },
    });
    expect(decision.permissionDecision).toBe("deny");
    expect(decision.permissionDecisionReason).toContain("openai/gpt-5.6-terra (missing)");
    expect(decision.permissionDecisionReason).toContain("cli agents mode architect off");
  });

  it("stays silent when the architect gate is explicitly off", () => {
    expect(architectDecision(exitPlan(VALID), () => { throw new Error("must not run"); }, {
      gate: { mode: "off", available: false, candidate: null, candidates: [] },
    })).toBeNull();
    expect(architectDecision(exitPlan(DISCUSSION), () => { throw new Error("must not run"); })).toBeNull();
  });

  it("does not invoke the architect for another broadly wired tool", () => {
    let calls = 0;
    const seen = architectDecision(
      { tool_name: "Bash", tool_input: { plan: VALID } },
      () => { calls += 1; return { ok: true, text: "VERDICT: issue" }; },
      { gate: AVAILABLE },
    );
    expect(seen).toBeNull();
    expect(calls).toBe(0);
  });
});

describe("architectDecision · the review bar and the preceding round", () => {
  const AVAILABLE = {
    mode: "agent",
    available: true,
    candidate: { label: "anthropic/claude-opus-5-5" },
    candidates: [],
  };
  const memory = () => {
    const states = new Map();
    return {
      states,
      read: (s) => (states.has(s) ? states.get(s) : (() => { throw new Error("ENOENT"); })()),
      write: (s, v) => states.set(s, JSON.parse(JSON.stringify(v))),
      clear: (s) => states.delete(s),
    };
  };
  const withSession = (plan, session = "s-1") => ({ ...exitPlan(plan), session_id: session, cwd: os.tmpdir() });
  const answer = (text) => () => ({ ok: true, text });

  it("builds the prompt from the shared bar, without the old adversarial wording", () => {
    let prompt = "";
    architectDecision(withSession(VALID), (_d, p) => { prompt = p; return { ok: true, text: "VERDICT: approve" }; }, { gate: AVAILABLE, store: memory() });
    expect(prompt).toContain("BAR. A finding is critical or high only");
    expect(prompt).toContain("- [critical|high|medium|low] step N — substance — evidence");
    expect(prompt).not.toMatch(/unsafe or incomplete|adversarial/i);
    expect(prompt).not.toContain("PRECEDING ROUND");
  });

  it("lets medium and low through as notes and clears the stored round", () => {
    const store = memory();
    store.states.set("s-1", { plan: "old", steps: {}, findings: [] });
    const seen = architectDecision(withSession(VALID), answer([
      "- [medium] step 2 — retry 3 is generous — two would do",
      "- [high] step 1 — no scenario given",
      "VERDICT: issue",
    ].join("\n")), { gate: AVAILABLE, store });
    expect(seen).not.toHaveProperty("permissionDecision");
    expect(seen.additionalContext).toContain("ARCHITECT NOTES");
    expect(seen.additionalContext).toContain("[medium] step 2 — retry 3 is generous");
    expect(store.states.has("s-1")).toBe(false);
  });

  it("denies on a blocking finding and stores the round for the next call", () => {
    const store = memory();
    const seen = architectDecision(withSession(VALID), answer([
      "- [high] step 2 — verify does not cover idempotency — a duplicate delivery passes the gate",
      "Fix: verify: npm run test:queue -- --dup",
      "VERDICT: issue",
    ].join("\n")), { gate: AVAILABLE, store });
    expect(seen.permissionDecision).toBe("deny");
    expect(seen.permissionDecisionReason).toContain("1 blocking finding(s)");
    expect(seen.permissionDecisionReason).toContain("Fix: verify: npm run test:queue -- --dup");
    expect(store.states.get("s-1").findings[0]).toMatchObject({ level: "high", step: "2" });
    expect(Object.keys(store.states.get("s-1").steps)).toEqual(["1", "2"]);
  });

  it("re-checks the preceding findings first and downgrades a new high on an unchanged step", () => {
    const store = memory();
    architectDecision(withSession(VALID), answer("- [high] step 2 — verify misses duplicates — dup passes\nVERDICT: issue"), { gate: AVAILABLE, store });
    const revised = VALID.replace("verify: npm run test:queue", "verify: npm run test:queue -- --dup");
    let prompt = "";
    const seen = architectDecision(withSession(revised), (_d, p) => {
      prompt = p;
      return { ok: true, text: "- [high] step 1 — table has no index — slow lookups on replay\nVERDICT: issue" };
    }, { gate: AVAILABLE, store });
    expect(prompt).toContain("FIRST, re-check these findings from the preceding round of this plan");
    expect(prompt).toContain("- [high] step 2 — verify misses duplicates");
    expect(prompt).toContain("TASKS CHANGED SINCE THEN: 2");
    expect(seen).not.toHaveProperty("permissionDecision");
    expect(seen.additionalContext).toContain("[medium] step 1 — table has no index");
  });

  it("keeps a new high on a changed step blocking", () => {
    const store = memory();
    architectDecision(withSession(VALID), answer("- [high] step 2 — verify misses duplicates — dup passes\nVERDICT: issue"), { gate: AVAILABLE, store });
    const revised = VALID.replace("verify: npm run test:queue", "verify: npm run test:queue -- --dup");
    const seen = architectDecision(withSession(revised), answer("- [high] step 2 — dup flag does not exist — npm passes it to a runner that ignores it\nVERDICT: issue"), { gate: AVAILABLE, store });
    expect(seen.permissionDecision).toBe("deny");
  });

  it("drops a medium the author rejected in the step's why, never a high", () => {
    const store = memory();
    architectDecision(withSession(VALID), answer("- [high] step 2 — verify misses duplicates — dup passes\nVERDICT: issue"), { gate: AVAILABLE, store });
    const revised = VALID
      .replace("verify: npm run test:queue", "verify: npm run test:queue -- --dup")
      .replace("обработчик идемпотентен.\n", "обработчик идемпотентен.\n      отклонено: retry 3 is generous — повтор дешёвый\n");
    let prompt = "";
    const seen = architectDecision(withSession(revised), (_d, p) => {
      prompt = p;
      return { ok: true, text: "- [medium] step 2 — retry 3 is generous — two would do\nVERDICT: approve" };
    }, { gate: AVAILABLE, store });
    expect(prompt).toContain("REJECTED BY THE AUTHOR");
    expect(prompt).toContain("task 2: retry 3 is generous — повтор дешёвый");
    expect(seen).toBeNull();
  });

  it("runs a full round when the stored state cannot be read", () => {
    const store = memory();
    store.states.set("s-1", { broken: true });
    let prompt = "";
    const seen = architectDecision(withSession(VALID), (_d, p) => {
      prompt = p;
      return { ok: true, text: "- [high] step 1 — table lacks a key — duplicate rows on replay\nVERDICT: issue" };
    }, { gate: AVAILABLE, store });
    expect(prompt).not.toContain("PRECEDING ROUND");
    expect(seen.permissionDecision).toBe("deny");
  });

  it("still denies when the round cannot be stored", () => {
    const store = { read: () => null, write: () => { throw new Error("EACCES"); }, clear: () => {} };
    const seen = architectDecision(withSession(VALID), answer("- [high] step 1 — table lacks a key — duplicate rows\nVERDICT: issue"), { gate: AVAILABLE, store });
    expect(seen.permissionDecision).toBe("deny");
  });

  it("stores rounds per session under the data directory", () => {
    const appData = mkdtempSync(path.join(os.tmpdir(), "plan-reviews-"));
    try {
      const store = planReviewStore(appData);
      expect(() => store.read("a/b")).toThrow();
      store.write("a/b", { steps: {}, findings: [] });
      expect(store.read("a/b")).toEqual({ steps: {}, findings: [] });
      store.clear("a/b");
      expect(() => store.read("a/b")).toThrow();
    } finally { rmSync(appData, { recursive: true, force: true }); }
  });

  const COLON = "- [high] step 2: verify misses duplicates — dup passes\nVERDICT: issue";

  it("returns an answer with lines out of format to the model once, and judges the rewrite", () => {
    const prompts = [];
    const replies = [COLON, "- [high] step 2 — verify misses duplicates — dup passes\nVERDICT: issue"];
    const seen = architectDecision(withSession(VALID), (_d, p) => { prompts.push(p); return { ok: true, text: replies.shift() }; }, { gate: AVAILABLE, store: memory() });
    expect(prompts).toHaveLength(2);
    expect(prompts[1]).toContain("LINES NOT IN THE FORMAT:");
    expect(prompts[1]).toContain("- [high] step 2: verify misses duplicates");
    expect(seen.permissionDecision).toBe("deny");
    expect(seen.permissionDecisionReason).toContain("1 blocking finding(s) (critical/high): step 2.");
  });

  it("denies at once when a parsed blocking finding sits next to a line out of format", () => {
    const prompts = [];
    const seen = architectDecision(withSession(VALID), (_d, p) => {
      prompts.push(p);
      return { ok: true, text: "- [high] step 1 — table lacks a key — duplicate rows\n- [low] step 2: wording\nVERDICT: issue" };
    }, { gate: AVAILABLE, store: memory() });
    expect(prompts).toHaveLength(1);
    expect(seen.permissionDecision).toBe("deny");
    expect(seen.permissionDecisionReason).toContain("- [low] step 2: wording");
  });

  it("fails open with a format-retry label when the rewrite call fails", () => {
    const replies = [{ ok: true, text: COLON }, { ok: false, error: "timed out" }];
    const seen = architectDecision(withSession(VALID), () => replies.shift(), { gate: AVAILABLE, store: memory() });
    expect(seen).not.toHaveProperty("permissionDecision");
    expect(seen.additionalContext).toContain("ARCHITECT CHECK FAILED OPEN (format retry)");
  });

  it("passes the raw answer to the session when the rewrite is still out of format", () => {
    const seen = architectDecision(withSession(VALID), answer(COLON), { gate: AVAILABLE, store: memory() });
    expect(seen).not.toHaveProperty("permissionDecision");
    expect(seen.additionalContext).toContain("ARCHITECT ANSWER NOT IN FORMAT");
    expect(seen.additionalContext).toContain("- [high] step 2: verify misses duplicates");
  });

  it("asks for the strict format with an example in the first prompt", () => {
    let prompt = "";
    architectDecision(withSession(VALID), (_d, p) => { prompt = p; return { ok: true, text: "VERDICT: approve" }; }, { gate: AVAILABLE, store: memory() });
    expect(prompt).toContain("never by a colon");
    expect(prompt).toContain("Example: - [high] step 2 — verify does not run the new test");
    expect(prompt).toContain("returned for rewriting");
  });

  it("passes a plan whose architect answer has no verdict line", () => {
    expect(architectDecision(withSession(VALID), answer("looks fine"), { gate: AVAILABLE, store: memory() })).toBeNull();
  });
});

describe("parallelismBlock · the rules the runner actually keeps", () => {
  it.each(WAVE_RULES.map((r) => [r.rule, r]))("%s", (_rule, r) => {
    expect(r.example()).toEqual(r.expect);
  });

  it("puts every wave rule into the architect prompt", () => {
    const block = parallelismBlock();
    for (const r of WAVE_RULES) expect(block).toContain(`- ${r.rule}`);
    expect(block).toContain("a missing `needs`");
    let prompt = "";
    architectDecision(exitPlan(VALID), (_d, p) => { prompt = p; return { ok: true, text: "VERDICT: approve" }; }, {
      gate: { mode: "agent", available: true, candidate: { label: "x" }, candidates: [] },
    });
    expect(prompt).toContain("PARALLELISM — the runner builds each wave");
  });
});

describe("architectGateState · candidate availability", () => {
  const candidate = (label, available) => {
    const [provider, model] = label.split("/");
    return {
      provider: { engine: { id: provider === "openai" ? "codex" : "claude-code" } },
      check: () => ({ provider, model, binary: { available, reason: available ? null : "missing" } }),
    };
  };

  it("selects the first actually available candidate, including a reserve", () => {
    const state = architectGateState(undefined, {
      resolve: () => ({
        mode: "agent",
        runsAsAgent: true,
        candidates: [candidate("openai/gpt-5.6-terra", false), candidate("anthropic/claude-opus-5-5", true)],
      }),
    });
    expect(state.available).toBe(true);
    expect(state.candidate.label).toBe("anthropic/claude-opus-5-5");
  });
});

// End to end through the dispatcher, because the promise "a hook never breaks a
// session" is about the PROCESS: exit 0 always, and stdout that is either empty
// or exactly one JSON object.
describe("cli.mjs plan-guard · the process", () => {
  let appData;
  beforeAll(() => {
    appData = mkdtempSync(path.join(os.tmpdir(), "plan-guard-process-"));
    const appDir = path.join(appData, "com.cu.app");
    mkdirSync(appDir, { recursive: true });
    const config = emptyAgentConfig();
    config.duties.architect.mode = "off";
    writeFileSync(path.join(appDir, "agents.json"), JSON.stringify(config));
  });
  afterAll(() => rmSync(appData, { recursive: true, force: true }));

  const runGuard = (input) =>
    execFileSync(process.execPath, [CLI, "plan-guard"], {
      encoding: "utf8",
      input,
      windowsHide: true,
      env: { ...process.env, APPDATA: appData, CODEX_BIN: path.join(path.dirname(CLI), "no-such-codex.exe") },
    });

  it("emits the deny payload for a broken plan and exits 0", () => {
    const out = runGuard(JSON.stringify(exitPlan(BROKEN)));
    const parsed = JSON.parse(out);
    expect(parsed.hookSpecificOutput.hookEventName).toBe("PreToolUse");
    expect(parsed.hookSpecificOutput.permissionDecision).toBe("deny");
    expect(parsed.hookSpecificOutput.permissionDecisionReason).toContain("on-issue");
    // One object, nothing else — extra stdout would be parsed as part of it.
    expect(out.trim().split("\n")).toHaveLength(1);
  });

  it("stays silent on a valid plan, on empty stdin and on garbage", () => {
    for (const input of ["", "   ", "not json at all", "[]", "null", JSON.stringify(exitPlan(VALID))])
      expect(runGuard(input)).toBe("");
  });
});

